const std = @import("std"); const reci = @import("ru-reci-main.zig"); const jobs = @import("ru-jobs-tabl.zig");
fn parse(aren: std.mem.Allocator, text: []const u8) !reci.Cmd { return (try reci.parse(aren, text)) orelse error.TestUnexpectedResult; }
test "get with a format maps to fetch-run params" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const txt = try parse(aren.allocator(), "Get https://example.com as text"); try std.testing.expectEqualStrings("fetch-run", txt.job); try std.testing.expectEqualStrings("https://example.com", txt.args.url); try std.testing.expectEqualStrings("response_type=plaintext", txt.args.opt); const jsn = try parse(aren.allocator(), "scrape https://a.co/x as JSON"); try std.testing.expectEqualStrings("json_response=true", jsn.args.opt); const mdn = try parse(aren.allocator(), "get https://a.co as markdown"); try std.testing.expectEqualStrings("response_type=markdown", mdn.args.opt); const plain = try parse(aren.allocator(), "get https://a.co"); try std.testing.expectEqualStrings("", plain.args.opt); }
test "account, data, money and help phrases" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); try std.testing.expectEqualStrings("signup", (try parse(al, "sign up")).job); try std.testing.expectEqualStrings("login", (try parse(al, "log in")).job); try std.testing.expectEqualStrings("logout", (try parse(al, "Log out")).job); const ver = try parse(al, "verify 123456"); try std.testing.expectEqualStrings("verify-email", ver.job); try std.testing.expectEqualStrings("123456", ver.args.text); try std.testing.expectEqualStrings("usage-view", (try parse(al, "show usage")).job); try std.testing.expectEqualStrings("plan-view", (try parse(al, "show plan")).job); const key = try parse(al, "create key My Key"); try std.testing.expectEqualStrings("key-create", key.job); try std.testing.expectEqualStrings("My Key", key.args.title); const inv = try parse(al, "invite bob@example.com"); try std.testing.expectEqualStrings("bob@example.com", inv.args.to); const up = try parse(al, "upgrade to Business"); try std.testing.expectEqualStrings("plan-change", up.job); try std.testing.expectEqualStrings("Business", up.args.opt); const docs = try parse(al, "docs rate limits"); try std.testing.expectEqualStrings("rate limits", docs.args.text); }
test "unknown words are not understood; every rule names a real job" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); try std.testing.expect((try reci.parse(aren.allocator(), "tell me a joke")) == null); for (reci.RULES) |rul| try std.testing.expect(jobs.find(rul.job) != null); }
